	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/cortes", wrapper.ListarCortes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/cortes", wrapper.CrearCorte)
